 "content": "def transform(grid):
    """Copy the nonzero pattern around the populated 5 marker to the isolated 5."""
    out = [row[:] for row in grid]
    markers = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 5]
    if len(markers) < 2:
        return out

    def neighborhood_count(pos):
        r0, c0 = pos
        return sum(
            1
            for r in range(max(0, r0 - 4), min(len(grid), r0 + 5))
            for c in range(max(0, c0 - 4), min(len(grid[0]), c0 + 5))
            if (r, c) != pos and grid[r][c] != 0
        )

    source = max(markers, key=neighborhood_count)
    target = min((p for p in markers if p != source), key=neighborhood_count)
    sr, sc = source
    tr, tc = target
    # Stamp the source motif, preserving the source marker and clearing the destination marker.
    out[tr][tc] = 0
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value and (r, c) != source:
                rr, cc = tr + r - sr, tc + c - sc
                if 0 <= rr < len(out) and 0 <= cc < len(out[0]):
                    out[rr][cc] = value
    return out
